// Raccoon Dance art (port of src/kpapp/game/dance/art.py): the stage, the
// coach's head, FX and UI sprites, generated by tools/generate_dance_assets.py
// into assets/dance/generated/ with a manifest.json carrying the numbers that
// belong to the art (outfit and rating colours, where the lights hang).
//
// The manifest's colours are OpenCV BGR; this loader turns every one into RGB,
// so nothing downstream has to remember (AGENTS.md section 11).
//
// Nothing here touches the DOM until loadArt() is called, so game.js can
// import it under Node.

import { loadImage, loadJSON } from "../../core/gfx.js";

export const ASSET_URL = new URL("../../../assets/dance/generated/", import.meta.url);
export const RATINGS = ["perfect", "super", "good", "ok", "x"];
export const WORDS = ["get_ready", "count_3", "count_2", "count_1", "count_go", "superstar"];
const GENERATOR = "uv run python tools/generate_dance_assets.py";

/** [b, g, r] -> [r, g, b]: for every colour that comes from the Python side. */
export const bgr = (c) => [c[2], c[1], c[0]];

const IMAGES = {
  stage: "stage.png", glowTrims: "glow_trims.png", glowFloor: "glow_floor.png", glowEdge: "glow_edge.png",
  beam: "beam.png", glow: "glow.png", sparkle: "sparkle.png", burst: "burst.png", ring: "ring.png",
  starFull: "star_full.png", starEmpty: "star_empty.png", card: "card.png", cardGold: "card_gold.png",
  head: "coach_head.png", headRim: "coach_head_rim.png",
};

/**
 * DanceArt: the images above, `words` (rating and banner words), and the
 * manifest with RGB colours. `outfit(name)` and `ratingColour(key)` as in art.py.
 */
export class DanceArt {
  constructor(images, words, manifest) {
    Object.assign(this, images);
    this.words = words;
    this.manifest = toRgb(manifest);
  }

  outfit(name) {
    const outfits = this.manifest.outfits ?? {};
    return outfits[name ?? "neon"] ?? outfits.neon ?? Object.values(outfits)[0] ?? {};
  }

  ratingColour(key) {
    return this.manifest.ratings?.[key]?.colour ?? [255, 255, 255];
  }
}

/** The manifest with every BGR colour as RGB (outfits, ratings, colours). */
function toRgb(spec) {
  const out = structuredClone(spec ?? {});
  for (const o of Object.values(out.outfits ?? {})) for (const k of Object.keys(o)) o[k] = bgr(o[k]);
  for (const r of Object.values(out.ratings ?? {})) if (r.colour) r.colour = bgr(r.colour);
  for (const k of Object.keys(out.colours ?? {})) out.colours[k] = bgr(out.colours[k]);
  return out;
}

let cache = null;
let pending = null;

export function cachedArt() {
  return cache;
}

export async function loadArt({ reload = false } = {}) {
  if (cache && !reload) return cache;
  if (pending && !reload) return pending;
  const url = (name) => new URL(name, ASSET_URL).href;
  pending = (async () => {
    let spec;
    try {
      spec = await loadJSON(url("manifest.json"));
    } catch (err) {
      throw new Error(`Raccoon Dance art is missing (${err.message}). Run: ${GENERATOR}`);
    }
    const img = (name) => loadImage(url(name)).catch(() => {
      throw new Error(`missing assets/dance/generated/${name}. Run: ${GENERATOR}`);
    });
    const names = Object.keys(IMAGES);
    const wordNames = [...RATINGS, ...WORDS];
    const [imgs, words] = await Promise.all([
      Promise.all(names.map((k) => img(IMAGES[k]))),
      Promise.all(wordNames.map((k) => img(`word_${k}.png`))),
    ]);
    cache = new DanceArt(Object.fromEntries(names.map((k, i) => [k, imgs[i]])),
      Object.fromEntries(wordNames.map((k, i) => [k, words[i]])), spec);
    return cache;
  })();
  try {
    return await pending;
  } finally {
    pending = null;
  }
}

/** Placeholder art with the right shapes and manifest keys, for Node tests (no pixels). */
export function stubArt() {
  const sprite = (width, height) => ({ width, height });
  const outfit = Object.fromEntries(["fur", "fur_dark", "top", "top_hi", "pants", "accent", "glove", "shoe",
    "rim", "glow"].map((k) => [k, [200, 100, 200]]));
  outfit.ink = [30, 20, 25];
  const images = {
    stage: sprite(1280, 720), glowTrims: sprite(320, 180), glowFloor: sprite(320, 180), glowEdge: sprite(320, 180),
    beam: sprite(260, 640), glow: sprite(64, 64), sparkle: sprite(72, 72), burst: sprite(420, 420),
    ring: sprite(140, 140), starFull: sprite(64, 64), starEmpty: sprite(64, 64), card: sprite(192, 208),
    cardGold: sprite(192, 208), head: sprite(256, 256), headRim: sprite(256, 256),
  };
  const words = Object.fromEntries([...RATINGS, ...WORDS].map((k) => [k, sprite(60 + 10 * k.length, 30)]));
  return new DanceArt(images, words, {
    outfits: { neon: outfit },
    ratings: Object.fromEntries(RATINGS.map((k) => [k, { colour: [255, 255, 255] }])),
    head: { centre: [0.5, 0.565], chin: [0.5, 0.8], face_width: 0.67 },
    stage: { lights: [[170, 94], [520, 94], [870, 94]], horizon: 470, spot: [520, 652, 250, 56], coach: [520, 660] },
    light_scale: 4,
  });
}
